awk '
BEGIN{
  print "**Reproduced Table 4: Field Immutability Results for OpenJDK**\n"
  printf("| Algorithm  | mutable | ⊒ non-trans. | ⊒ depen. | ⊒ trans. |\n")
  printf("| ---------- | ------: | -----------: | -------: | -------: |\n")
}
/^algorithm:/ {alg_raw=$2; alg=alg_raw; if(alg=="AdHocCHA") alg="Ad-hoc CHA";}
/^ Mutable Fields:/ {m=$3}
/^ Non Transitively Immutable Fields:/ {n=$5}
/^ Dependently Immutable Fields:/ {d=$4}
/^ Transitively Immutable Fields:/ {t=$4; if(t=="") t=$5}
/^Transitively Immutable Fields:/ {
  # print row when we have collected values
  # format numbers with spaces like the paper (grouping by thousands)
  cmd1 = "echo " m " | sed -E 's/([0-9]+)([0-9]{3})$/\\1 \\2/'"
  cmd2 = "echo " n " | sed -E 's/([0-9]+)([0-9]{3})$/\\1 \\2/'"
  cmd3 = "echo " d " | sed -E 's/([0-9]+)([0-9]{3})$/\\1 \\2/'"
  cmd4 = "echo " t " | sed -E 's/([0-9]+)([0-9]{3})$/\\1 \\2/'"
  cmd1 | getline mm; close(cmd1)
  cmd2 | getline nn; close(cmd2)
  cmd3 | getline dd; close(cmd3)
  cmd4 | getline tt; close(cmd4)
  printf("| %-10s | %6s | %11s | %7s | %8s |\n", alg, mm, nn, dd, tt)
}
' /workspace/summaries/immutability_results.txt > /workspace/repro.txt

